 if(id==='sudoku'){const b=['530070000','600195000','098000060','800060003','400803001','700020006','060000280','000419005','000080079'].map(s=>s.split('').map(Number));const safe=(r,c,v)=>{for(let i=0;i<9;i++)if(b[r][i]===v||b[i][c]===v)return false;const rr=Math.floor(r/3)*3,cc=Math.floor(c/3)*3;for(let i=rr;i<rr+3;i++)for(let j=cc;j<cc+3;j++)if(b[i][j]===v)return false;return true};let ticks=0;function solve(){let r=-1,c=-1;outer:for(let i=0;i<9;i++)for(let j=0;j<9;j++)if(!b[i][j]){r=i;c=j;break outer}if(r<0)return true;for(let v=1;v<=9;v++)if(safe(r,c,v)){b[r][c]=v;add({sudoku:b.map(x=>x.slice()),r,c},`Try ${v} at (${r+1},${c+1}); candidate is legal.`);if(++ticks>6000)return false;if(solve())return true;b[r][c]=0;add({sudoku:b.map(x=>x.slice()),r,c},`Backtrack: remove ${v} at (${r+1},${c+1}).`)}return false}const ok=solve();add({sudoku:b.map(x=>x.slice()),r:0,c:0,solved:ok},ok?'Sudoku solved.':'Stopped after trace limit.');return S}
