  useDsa('bst','8,3,10,1,6,14,4,7,13');eq(F_treeOrder([8,3,10,1,6,14,4,7,13],'in'),[1,3,4,6,7,8,10,13,14],'BST in-order traversal is sorted');
  useDsa('avl','1,2,3,4,5,6,7,8,9');const avlRoot=F_buildAVL([1,2,3,4,5,6,7,8,9]);const balanced=n=>!n||Math.abs((n.l?.h||0)-(n.r?.h||0))<=1&&balanced(n.l)&&balanced(n.r);ok(balanced(avlRoot),'AVL insertions preserve balance factors');
  useDsa('heapds','9,1,8,2,7,3,6,4,5');const heapStep=run.steps.find(step=>/build max heap/i.test(step.text));ok(!!heapStep&&heapStep.nodes.every((v,i,a)=>i===0||a[Math.floor((i-1)/2)]>=v),'Binary heap construction satisfies the max-heap property');
  useDsa('segment','1,2,3,4,5');ok(run.steps.some(step=>/Range query \[0,3\] returns 10/.test(step.text||'')),'Segment-tree range sum returns 10 for [0,3]');
  useDsa('fenwick','1,2,3,4');ok(run.steps.some(step=>/Prefix sum through index 2 = 6/.test(step.text||'')),'Fenwick prefix sum returns 6 through index 2');
