  useDsa('stack','1,2,3');eq(last('stack').nodes,[],'Stack finishes empty after LIFO push/pop trace');
  useDsa('queue','1,2,3');eq(last('queue').nodes,[],'Queue finishes empty after FIFO enqueue/dequeue trace');
