  for(const id of ['prim','kruskal'])eq(gs=graph(id),gs,`${id} trace generated`); // also validate both selected edge sets below
  for(const id of ['prim','kruskal']){gs=graph(id);const mst=gs.at(-1).mst||[];eq(mst.length,5,`${id} builds a spanning tree with n−1 edges`);eq(mst.reduce((sum,e)=>sum+e[2],0),7,`${id} minimum spanning tree weight`)}
